tool_use_result.content:
server {
    listen 8443 ssl;
    server_name localhost;

    ssl_certificate /etc/nginx/certs/certificate.crt;
    ssl_certificate_key /etc/nginx/certs/private.key;

    # Root location for main branch
    location / {
        root /var/www/main;
        try_files $uri $uri/ =404;
    }

    # Dev branch at /dev
    location /dev/ {
        alias /var/www/dev/;
        try_files $uri $uri/ =404;
    }
}

